if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.error("No es .json");
        return null;
    }
}

// Salidas
return [
    { topic: "ecg", payload: data.ecg },
    { topic: "roll_a", payload: data.roll_a },
    { topic: "pitch_a", payload: data.pitch_a },
    { topic: "yaw_a", payload: data.yaw_a },
    { topic: "roll_f", payload: data.roll_f },
    { topic: "pitch_f", payload: data.pitch_f },
    { topic: "yaw_f", payload: data.yaw_f }
];

// 1. Recuperar estado previo
let imu = flow.get("imu") || {
    rollA: 0, pitchA: 0, yawA: 0,
    rollF: 0, pitchF: 0, yawF: 0
};

let d = msg.payload;

// 2. AUTO-PARSE: Si el payload llega como String (común en MQTT), lo convertimos a Objeto
if (typeof d === "string") {
    try {
        d = JSON.parse(d);
    } catch (e) {
        // Si no es un JSON válido, no hacemos nada con 'd'
    }
}

// 3. TRADUCCIÓN: Si es un objeto y tiene los datos del sensor (con guiones bajos)
if (typeof d === "object" && d !== null) {
    if (d.hasOwnProperty('roll_a')) imu.rollA = Number(d.roll_a);
    if (d.hasOwnProperty('pitch_a')) imu.pitchA = Number(d.pitch_a);
    if (d.hasOwnProperty('yaw_a')) imu.yawA = Number(d.yaw_a);

    if (d.hasOwnProperty('roll_f')) imu.rollF = Number(d.roll_f);
    if (d.hasOwnProperty('pitch_f')) imu.pitchF = Number(d.pitch_f);
    if (d.hasOwnProperty('yaw_f')) imu.yawF = Number(d.yaw_f);
}

// 4. SLIDERS: Si el mensaje tiene un topic que coincide con nuestras llaves
if (msg.topic && imu.hasOwnProperty(msg.topic)) {
    imu[msg.topic] = Number(msg.payload);
}

// 5. LIMPIEZA Y SALIDA: Construimos el JSON final para el WebSocket
let finalPayload = {
    rollA: Number(imu.rollA || 0),
    pitchA: Number(imu.pitchA || 0),
    yawA: Number(imu.yawA || 0),
    rollF: Number(imu.rollF || 0),
    pitchF: Number(imu.pitchF || 0),
    yawF: (Number(imu.yawF || 0))
};

flow.set("imu", finalPayload);
msg.payload = JSON.stringify(finalPayload);

return msg;

let d = msg.payload;

if (typeof d === "string") {
    d = JSON.parse(d);
}

// 👇 IMPORTANTE: measurement fuera del payload
msg.measurement = "prototype_data";

// 👇 SOLO fields en payload
msg.payload = {
    rollA: parseFloat(d.roll_a),
    pitchA: parseFloat(d.pitch_a),
    yawA: parseFloat(d.yaw_a),
    rollF: parseFloat(d.roll_f),
    pitchF: parseFloat(d.pitch_f),
    yawF: parseFloat(d.yaw_f),
    ecg: parseFloat(d.ecg)
};

return msg;

let data = flow.get("imu_values") || {
    "roll_f": 0, "pitch_f": 0, "yaw_f": 0,
    "roll_a": 0, "pitch_a": 0, "yaw_a": 0
};

switch (msg.topic) {
    case "rollF":  data.roll_f  = msg.payload; break;
    case "pitchF": data.pitch_f = msg.payload; break;
    case "yawF":   data.yaw_f   = msg.payload; break;
    case "rollA":  data.roll_a  = msg.payload; break;
    case "pitchA": data.pitch_a = msg.payload; break;
    case "yawA":   data.yaw_a   = msg.payload; break;
}

flow.set("imu_values", data);
msg.payload = data;
return msg;

// Verificar si el mensaje viene del selector de ejercicios (tiene el campo 'ejercicio' o es un número simple)
if (msg.hasOwnProperty('ejercicio') || (typeof msg.payload !== 'object' && !isNaN(msg.payload))) {
    // Es el selector de ejercicios
    let ejercicio = msg.ejercicio || msg.payload;
    flow.set("ejercicio_seleccionado", ejercicio.toString());
    return null; // No procesar más
}

// Asegurar que payload sea objeto
let data = msg.payload;

// Si viene del JSON, procesar los datos del sensor
if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.error("No es .json");
        return null;
    }
}

// Si no tiene las propiedades esperadas, ignorar
if (!data.hasOwnProperty('roll_a')) {
    return null;
}

// Extraer valores de los ángulos
let roll_a = data.roll_a;
let pitch_a = data.pitch_a;
let yaw_a = data.yaw_a;
let roll_f = data.roll_f;
let pitch_f = data.pitch_f;
let yaw_f = data.yaw_f;

// Obtener el ejercicio seleccionado (del flow context)
let ejercicio = flow.get("ejercicio_seleccionado") || "1";

// Función para verificar si un valor está dentro del rango seguro (color verde)
function isInSafeRange(valor, ejercicio, variable) {
    let rangos = {};

    if (ejercicio === "1") {
        rangos = {
            roll_a: [{ min: -10, max: 10 }],
            // Pitch A tiene dos zonas verdes en ejercicio 1
            pitch_a: [{ min: -10, max: 10 }, { min: 80, max: 90 }],
            yaw_a: [{ min: 80, max: 90 }],
            roll_f: [{ min: -10, max: 10 }],
            pitch_f: [{ min: -10, max: 10 }],
            yaw_f: [{ min: -10, max: 10 }]
        };
    } else if (ejercicio === "2") {
        rangos = {
            roll_a: [{ min: -10, max: 10 }],
            pitch_a: [{ min: -10, max: 10 }],
            yaw_a: [{ min: -10, max: 10 }],
            // Roll F tiene dos zonas verdes en ejercicio 2
            roll_f: [{ min: -10, max: 10 }, { min: 80, max: 90 }],
            pitch_f: [{ min: -10, max: 10 }],
            yaw_f: [{ min: 80, max: 90 }]
        };
    } else if (ejercicio === "3") {
        rangos = {
            roll_a: [{ min: 80, max: 90 }],
            pitch_a: [{ min: -30, max: 30 }],
            yaw_a: [{ min: -90, max: 80 }],
            roll_f: [{ min: 80, max: 90 }],
            pitch_f: [{ min: -30, max: 30 }],
            yaw_f: [{ min: -90, max: 80 }]
        };
    }

    let zonasSeguras = rangos[variable];
    if (!zonasSeguras) return true;

    // Verificamos si el valor entra en CUALQUIERA de los rangos definidos
    return zonasSeguras.some(rango => (valor >= rango.min && rango.max >= valor));
}

// Verificar cada variable
let variables = [
    { nombre: "roll_a", valor: roll_a, label: "Roll A" },
    { nombre: "pitch_a", valor: pitch_a, label: "Pitch A" },
    { nombre: "yaw_a", valor: yaw_a, label: "Yaw A" },
    { nombre: "roll_f", valor: roll_f, label: "Roll F" },
    { nombre: "pitch_f", valor: pitch_f, label: "Pitch F" },
    { nombre: "yaw_f", valor: yaw_f, label: "Yaw F" }
];

let valoresFueraDeRango = [];
let hayAlerta = false;

for (let v of variables) {
    if (!isInSafeRange(v.valor, ejercicio, v.nombre)) {
        valoresFueraDeRango.push(v.label);
        hayAlerta = true;
    }
}

// Enviar datos originales separados (para los gauges)
let datosSeparados = [
    { topic: "ecg", payload: data.ecg },
    { topic: "roll_a", payload: data.roll_a },
    { topic: "pitch_a", payload: data.pitch_a },
    { topic: "yaw_a", payload: data.yaw_a },
    { topic: "roll_f", payload: data.roll_f },
    { topic: "pitch_f", payload: data.pitch_f },
    { topic: "yaw_f", payload: data.yaw_f - data.yaw_a }
];

// Si hay alerta, activar sonido y notificación
if (hayAlerta) {
    let mensajeAlerta = `⚠️ Alerta: ${valoresFueraDeRango.join(", ")} fuera de rango`;

    // Mensaje para el banner visual
    let bannerMsg = { 
        payload: mensajeAlerta,
        background: "#ea5353",
        textColor: "#ffffff"
    };

    // Notificación emergente
    let notificacion = {
        payload: mensajeAlerta
    };

    // Enviar múltiples salidas
    return [
        datosSeparados,  // Salida 0: Datos para los gauges
        null,            // Salida 1: Reservada
        bannerMsg,       // Salida 2: Banner visual
        notificacion,    // Salida 3: Notificación
        { payload: true } // Salida 4: Sonido/buzzer
    ];
} else {
    // Sin alerta - banner en verde
    let bannerMsg = {
        payload: "✅ Todos los parámetros en rango",
        background: "#5cd65c",
        textColor: "#ffffff"
    };

    return [
        datosSeparados,  // Salida 0: Datos para los gauges
        null,            // Salida 1: Reservada
        bannerMsg,       // Salida 2: Banner verde
        null,            // Salida 3: Sin notificación
        null             // Salida 4: Sin sonido
    ];
}

const targets = [
    { value: -90, range: 25 },
    { value: -45, range: 20 },
    { value: 0, range: 25 },
    { value: 45, range: 20 },
    { value: 90, range: 25 }
];

function snapValue(val) {
    for (let t of targets) {
        if (val >= (t.value - t.range) && val <= (t.value + t.range)) {
            return t.value;
        }
    }
    return val;
}

const fields = ["roll_f", "pitch_f", "yaw_f", "roll_a", "pitch_a", "yaw_a"];

fields.forEach(field => {
    if (msg.payload.hasOwnProperty(field)) {
        msg.payload[field] = snapValue(msg.payload[field]);
    }
});

// Restar yaw_a de yaw_f, y roll_a de roll_f
if (msg.payload.hasOwnProperty('yaw_f') && msg.payload.hasOwnProperty('yaw_a')) {
    msg.payload.yaw_f = msg.payload.yaw_f - msg.payload.yaw_a;
}

if (msg.payload.hasOwnProperty('roll_f') && msg.payload.hasOwnProperty('roll_a')) {
    msg.payload.roll_f = msg.payload.roll_f - msg.payload.roll_a;
}

return msg;
